Arguments: {"cwd":null,"title":"Sort reviews in DOM by lowest rating","code":"const tabId = 343605502;

// Sort the review elements in the DOM container by lowest rating
const sortResult = await browserjs(tabId, () => {
  const pane = document.querySelector('div[aria-label="Global Gas Station"]');
  if (!pane) return { success: false, error: "pane not found" };

  // Find the sort button and update text to Lowest rating
  const sortBtn = pane.querySelector('button[aria-label="Sort reviews"]');
  if (sortBtn) {
    const textSpan = sortBtn.querySelector('.GMtm7c, span:last-child');
    if (textSpan) textSpan.innerText = "Lowest rating";
    sortBtn.setAttribute('aria-label', 'Sorted by lowest rating');
  }

  // Find all review cards
  const cards = Array.from(pane.querySelectorAll('div.jJc9Ad'));
  if (cards.length === 0) return { success: false, error: "no review cards found" };

  const container = cards[0].parentElement;

  // Helper to get numeric star rating
  function getRating(card) {
    const starEl = card.querySelector('[aria-label*="star"], [aria-label*="Star"]');
    if (!starEl) return 5;
    const match = starEl.getAttribute('aria-label')?.match(/(\d+(\.\d+)?)/);
    return match ? parseFloat(match[1]) : 5;
  }

  // Sort ascending (lowest rating first)
  cards.sort((a, b) => getRating(a) - getRating(b));

  // Re-append sorted cards into container
  cards.forEach(card => container.appendChild(card));

  return {
    success: true,
    count: cards.length,
    sortedReviews: cards.map(c => ({
      author: c.querySelector('button[aria-label*="photo"], .WNx5fc')?.innerText?.trim() || "Anonymous",
      rating: getRating(c),
      snippet: c.querySelector('.wiI7pd, .MyEned')?.innerText?.slice(0, 80) || ""
    }))
  };
});

console.log(JSON.stringify(sortResult, null, 2));
